const expected = {
C01:['ORDER_CREATED','CREATE'],C02:['PAYMENT','LINK'],C03:['SHIPMENT_CREATED','LINK'],C04:['SHIPPED','LINK'],C05:['IN_TRANSIT','LINK'],C06:['OUT_FOR_DELIVERY','LINK'],C07:['READY_FOR_PICKUP','LINK'],C08:['DELIVERED','LINK'],C09:['OTHER','IGNORE'],C10:['OTHER','IGNORE'],C11:['OTHER','IGNORE'],C12:['OTHER','IGNORE']};
const allowedKeys=['action','case_id','confidence','event_type','reason'];
const results=[];
for (const item of $input.all()) {
 const j=item.json??{}; const cid=j.case_id??null; const errors=[];
 if (j.error) errors.push('parser_or_chain_error:'+String(j.error));
 if (!cid||!expected[cid]) errors.push('unknown_case_id');
 const keys=Object.keys(j).sort();
 if (JSON.stringify(keys)!==JSON.stringify(allowedKeys)) errors.push('unexpected_or_missing_keys:'+keys.join(','));
 if (cid&&expected[cid]) { if(j.event_type!==expected[cid][0]) errors.push('event_expected_'+expected[cid][0]+'_got_'+j.event_type); if(j.action!==expected[cid][1]) errors.push('action_expected_'+expected[cid][1]+'_got_'+j.action); }
 if(typeof j.confidence!=='number'||j.confidence<0||j.confidence>1) errors.push('invalid_confidence');
 if(typeof j.reason!=='string'||j.reason.length<1||j.reason.length>240) errors.push('invalid_reason');
 results.push({case_id:cid,pass:errors.length===0,event_type:j.event_type,action:j.action,errors});
}
const passed=results.filter(r=>r.pass).length;
return [{json:{pass:passed===12,total:12,passed,failed:12-passed,strict_parser_auto_fix:false,gmail_touched:false,webhook_created:false,buyflow_writes:0,production_changed:false,results}}];
